#!/bin/bash
# Writes App/Shared/Core/Secrets.swift from the environment (CI: repository secrets). The values are stored XOR-ed so they
# are not readable strings in the binary; this is obfuscation for a personal build, not protection.
set -euo pipefail
cd "$(dirname "$0")/.."
python3 - <<'PY'
import os
def enc(s):
    return ', '.join(str(b ^ 0x5A) for b in s.encode('utf-8'))
mega = os.environ.get('MEGAOTT_API_TOKEN', '')
tmdb = os.environ.get('TMDB_API_KEY', '')
src = '''import Foundation

/// Generated by scripts/write_secrets.sh — not in git.
enum Secrets {
    private static func dec(_ b: [UInt8]) -> String { String(decoding: b.map { $0 ^ 0x5A }, as: UTF8.self) }
    static let megaOttToken: String = dec([%s])
    static let tmdbKey: String = dec([%s])
}
''' % (enc(mega), enc(tmdb))
os.makedirs('App/Shared/Core', exist_ok=True)
open('App/Shared/Core/Secrets.swift', 'w').write(src)
print('Secrets.swift written (mega %d chars, tmdb %d chars)' % (len(mega), len(tmdb)))
PY
